code.java:
public int gcd(int a, int b) {
    a = Math.abs(a);
    b = Math.abs(b);
    while (b != 0) {
        int r = a % b;
        a = b;
        b = r;
    }
    return a;
}

// LCM as a bonus: divide before multiplying to avoid overflow
public long lcm(int a, int b) {
    if (a == 0 || b == 0) return 0;
    return (long) (Math.abs(a) / gcd(a, b)) * Math.abs(b);
}

