def gcd(self, a: int, b: int) -> int:
    a, b = abs(a), abs(b)
    while b != 0:
        a, b = b, a % b
    return a

def lcm(self, a: int, b: int) -> int:
    if a == 0 or b == 0:
        return 0
    return abs(a) // self.gcd(a, b) * abs(b)

